"""Evaluation helpers.  Scores first, labels second: labels are consumed only
after anomaly scores exist (requirements R9, R10)."""

from __future__ import annotations

import numpy as np
from sklearn.metrics import average_precision_score, precision_recall_curve, roc_auc_score


def roc_auc(scores: np.ndarray, y: np.ndarray) -> float:
    """AUC-ROC (requirement R9)."""
    return float(roc_auc_score(np.asarray(y).ravel(), np.asarray(scores).ravel()))


def auc_pr(scores: np.ndarray, y: np.ndarray) -> float:
    """Primary AUC-PR: average precision, the ADBench/PyOD convention (R9)."""
    return float(average_precision_score(np.asarray(y).ravel(), np.asarray(scores).ravel()))


def auc_pr_trapz(scores: np.ndarray, y: np.ndarray) -> float:
    """Secondary AUC-PR: trapezoidal area of the precision-recall curve."""
    prec, rec, _ = precision_recall_curve(np.asarray(y).ravel(),
                                          np.asarray(scores).ravel())
    return float(np.trapezoid(prec[::-1], rec[::-1]))


def summarize(values) -> dict:
    v = np.asarray(list(values), dtype=np.float64)
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=1)) if v.size > 1 else 0.0,
        "min": float(v.min()),
        "max": float(v.max()),
        "n": int(v.size),
        "values": [float(x) for x in v],
    }

