def variant(X,m,t,seed,inc_anchor=True):
    n=X.shape[0];rng=np.random.default_rng(seed+1000*m);tot=np.zeros(n);cnt=np.zeros(n)
    for k in range(t):
        a=sample_anchors(n,m,rng);cell,delta=assign_cells(X,X[a])
        c=np.bincount(cell,minlength=m);ds=np.bincount(cell,weights=delta,minlength=m)
        if inc_anchor:
            mean=ds/np.maximum(c,1)
        else:
            mean=ds/np.maximum(c-1,1)
        dmax=np.zeros(m);np.maximum.at(dmax,cell,delta)
        ok=(c[cell]>1)&(dmax[cell]>0)
        s=(delta/dmax[cell])*mean[cell]
        tot[ok]+=s[ok];cnt[ok]+=1
    return tot/np.maximum(cnt,1)
for m in [2,4,8]:
  for inc in [True,False]:
    v=[roc_auc(variant(X,m,100,s,inc),y) for s in [1,2,3]]
    print('m',m,'inc_anchor',inc,'AUC',np.round(v,4),'mean',round(np.mean(v),4))

